-- VX Capital Finance - Importacao do fluxo de caixa real (planilha do usuario)
-- Rodar no Supabase: Dashboard > SQL Editor > New query > colar e executar
-- Fonte: fluxo de caixa - Copia.xlsm (aba Base), 174 lancamentos de Fev-Mai/2026

-- 1) Conta bancaria para receber os lancamentos importados (edite o nome do banco depois em Contas Bancarias)
select 'Fluxo de Caixa Importado', 'corrente', 0
where not exists (select 1 from public.accounts where bank = 'Fluxo de Caixa Importado');

-- 2) Categorias usadas na planilha (cria somente as que ainda nao existem)
select v.name, v.color, v.type from (values
  ('Serviço', '#22C55E', 'receita'),
  ('Contabilidade', '#EF4444', 'despesa'),
  ('Tel. - Internet', '#EF4444', 'despesa'),
  ('Outros', '#22C55E', 'receita'),
  ('Aluguel', '#EF4444', 'despesa'),
  ('Taxas', '#EF4444', 'despesa'),
  ('Comercial/Marketing', '#EF4444', 'despesa'),
  ('Fornecedores', '#EF4444', 'despesa'),
  ('Ajuda de Custo / Diárias', '#EF4444', 'despesa'),
  ('Outros - Saída', '#EF4444', 'despesa'),
  ('Transporte', '#EF4444', 'despesa'),
  ('Hospedagem', '#EF4444', 'despesa'),
  ('Hospedagem', '#22C55E', 'receita'),
  ('Software', '#EF4444', 'despesa'),
  ('Pesquisa de Campo', '#EF4444', 'despesa'),
  ('Transporte', '#22C55E', 'receita')
) as v(name, color, type)
where not exists (select 1 from public.categories c where c.name = v.name and c.type = v.type);

-- 3) Lancamentos importados da planilha
;
